_A5 = [("Ano nga ba ang benepisyo ng pag-eehersisyo sa umaga?", "What are the benefits of exercising in the morning?"), ("Ayon sa pag-aaral ang ehersisyo ay nakakatulong para bumilis at tumalas ang kakayanang mag-isip ng tao apat hanggang sampung oras pagkatapos niyang mag-ehersisyo.", "According to a study, exercise helps a person’s ability to think become faster and sharper for four to ten hours after he exercises."), ("Nakakatulong ito para maging natural ang cycle ng ating pagtulog.", "It helps our sleep cycle become natural."), ("Dahil maagang nakakatulog maaga ring nagigising at nagiging handa ang ating katawan para sa buong araw na gawain.", "Because you fall asleep early, you also wake up early and our body becomes ready for the whole day’s activity."), ("Isang pangkaisipang benepisyo nito ay ang pag-iwas sa hindi masusutansiyang pagkain.", "One mental benefit of this is avoiding non-nutritious food."), ("Dahil nagsisimula ang araw mo sa pag-eehersisyo mas magiging maingat ka sa pagpili ng kakainin.", "Because your day starts with exercise, you will be more careful in choosing what you eat."), ("At mas iisipin mo kung ano ang mas nakabubuti para sa iyong kalusugan.", "And you will think more about what is better for your health.")]
_K5 = [["1", "benepisyo ng pag-eehersisyo sa umaga", "benefits of (morning) exercise"], ["2", "nakakatulong para bumilis", "helps to speed up"], ["3", "maaga ring nagigising", "also wakes up early"], ["4", "hindi masusutansiyang pagkain", "non-nutritious food"], ["5", "maingat ka sa pagpili ng kakainin", "careful in choosing food"], ["6", "nakabubuti para sa iyong kalusugan", "good for your health"]]
_A6A = [("Narito ang mga tip sa aking healthier cooking, eating, working out lifestyle.", "Here are the tips for my healthier cooking, eating, working out lifestyle."), ("Ang carbs ay dapat sa umaga, pagkatapos magwork-out at hanggang lunch dahil mahaba pa ang oras para i-burn at magamit ito.", "Carbs should be in the morning, after a workout and until lunch because there is still plenty of time to burn and use them."), ("Ideally ay mas kaunti na ang carbs habang gumagabi at sa gabi ay protina na lang.", "Ideally there are fewer carbs as the evening comes, and at night just protein."), ("Bagama’t sinusukat ko ang mga sangkap, ultimo ang bawat kutsara ng mayonnaise, ang gulay naman ay unlimited.", "Although I measure the ingredients, down to every spoon of mayonnaise, the vegetables are unlimited."), ("Napakababa ng calories ng mga gulay ngunit hitik sa sustansya, bitamina’t mineral.", "Vegetables are very low in calories but packed with nutrients, vitamins and minerals.")]
_A6B = [("Ang mangga at saging ang may pinakamataas na carbohydrate content sa lahat ng prutas, kaya dapat sa umaga lamang ang mga ito.", "Mango and banana have the highest carbohydrate content of all fruits, so they should be eaten only in the morning."), ("Imbes na asin ang pampalasa, subukan ang paminta at katas ng lemon.", "Instead of salt as a flavoring, try pepper and lemon juice."), ("Nakakatulong ang maaanghang sa pagpapapayat kaya mas damihan mo pa ang sili, chili powder at cayenne pepper sa pagkain.", "Spicy foods help in slimming, so add even more chili, chili powder and cayenne pepper to your food."), ("Uminom ng dalawang litro ng malamig na tubig kada araw.", "Drink two liters of cold water every day."), ("Mas malamig, mas mainam dahil puwersado ang katawang painitin ito.", "The colder, the better, because the body is forced to warm it."), ("Ang epekto, bibilis ang metabolism, madaling mabubusog, konti ang makakain.", "The effect is that the metabolism speeds up, you get full easily, and you eat little.")]
_L7 = [("Passage 1", "Importante na dapat tayong kumain ng iba’t ibang klase ng gulay araw-araw. So, kung iba’t-iba yung klase ng gulay na kinakain natin araw-araw, makukuha natin yung mga vitamins saka minerals na kinakailangan ng ating katawan para tayo ay mag-function nang maayos.", "It is important that we eat different kinds of vegetables every day. So if the kinds of vegetables we eat every day are different, we will get the vitamins and minerals that our body needs to function well."), ("Passage 2", "Kaya ang mga gulay ay mayaman sa sinasabi nating fiber. Yung fiber na yan ay hindi ito nada-digest. Ito ay parang walis sa ating intestines, sa ating bituka para malinisan at mawawala yung mga kolesterol sa ating katawan.", "So vegetables are rich in what we call fiber. That fiber is not digested. It is like a broom in our intestines, in our bowel, to clean it and get rid of the cholesterol in our body."), ("Passage 3", "Para yung mga nerve natin sa ating katawan ay maging maayos, at ganun din yung daloy ng ating dugo, gumanda rin yung ating kutis, luminaw ang ating mga mata, dun natin nakukuha yun sa glow foods, kaya glow food siya.", "So that the nerves in our body are in good order, and also the flow of our blood, our skin also becomes beautiful and our eyes become clear, we get that from glow foods, which is why it is a glow food."), ("Passage 4", "Ang ideal intake nasa nutritional guidelines natin ay isa hanggang isa’t kalahating cups na vegetables ang kinakailangan natin sa isang araw at kalahati dito ay dapat galing sa mabeberdeng gulay. Ang Filipinos ay meron lang isang cup ng vegetables ang intake nila. So parang nagkukulang pa tayo ng kalahating cup para lang sana ma-meet natin yung requirement natin sa vegetable consumption.", "The ideal intake in our nutritional guidelines is one to one and a half cups of vegetables that we need in a day, and half of this should come from green leafy vegetables. Filipinos only have one cup of vegetables for their intake. So we are still short by half a cup just so that we can meet our requirement for vegetable consumption.")]
_K7 = [("1", "It is important to eat different kinds of vegetables every day. If we do, we get the vitamins and minerals that our bodies need to function well."), ("2", "Vegetables are rich in fiber. Fiber is not digested. It is like a broom in our intestines that cleans and gets rid of cholesterol in the body."), ("3", "Vegetables make our nerves function well, contribute to good blood circulation, make our skin smooth, make our eyes clear, all of which we get from glow foods. That is why vegetables are called glow food."), ("4", "Based on nutritional guidelines, we need 1½ cups of vegetables daily, and ½ cup should be green leafy vegetables. Filipinos only have a cup; thus Filipinos need ½ more just to meet the daily required consumption or intake of vegetables.")]
