        + [M("When does exercise help the mind, according to the study?", "four to ten hours after exercising", ["only during exercise", "the next week", "for one minute"], "apat hanggang sampung oras."), M("What does morning exercise help adjust?", "the sleep cycle", ["the weight only", "the voice", "the height"], "cycle ng pagtulog."), M("What mental benefit is named?", "avoiding non-nutritious food", ["eating more sweets", "skipping meals", "buying more food"], "pag-iwas."), M("When should carbs be eaten?", "in the morning, after a workout and until lunch", ["only at night", "only at midnight", "never"], "umaga."), M("What should the evening meal be?", "protein", ["carbs", "sweets", "fruit"], "protina."), M("Which vegetables are unlimited?", "all vegetables", ["only carrots", "only potatoes", "none"], "unlimited."), M("Which fruits have the highest carbohydrate content?", "mango and banana", ["papaya and melon", "apple and pear", "grape and lemon"], "mangga at saging."), M("What should replace salt as a flavoring?", "pepper and lemon juice", ["more sugar", "soy sauce", "butter"], "paminta at katas ng lemon."), M("How much cold water should you drink daily?", "two liters", ["one cup", "five liters", "ten glasses of milk"], "dalawang litro."), M("Why is cold water recommended?", "the body is forced to warm it", ["it tastes sweet", "it is cheaper", "it is cleaner"], "puwersado ang katawan."), M("Why are vegetables compared to a broom?", "fiber cleans the intestines and gets rid of cholesterol", ["they are long", "they are green", "they are cheap"], "walis."), M("How many cups of vegetables do Filipinos eat daily, according to the passage?", "one", ["three", "half", "five"], "isang cup."), M("Why are vegetables called glow food?", "they help the skin and eyes", ["they shine in the dark", "they are orange", "they are hot"], "glow food.")]
